$ErrorActionPreference = "Stop"
$ProjectRoot = (Get-Location).Path
$Target = Join-Path $ProjectRoot "scripts\entity\repair-cached-emet-failures.js"
$PackagePath = Join-Path $ProjectRoot "package.json"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $ProjectRoot ".private\entity\backups\P04-targeted-final-repair-$Timestamp"

Write-Host "Installing P04 targeted final repair..." -ForegroundColor Cyan

if (-not (Test-Path (Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"))) {
    throw "Run this installer from the ai-bible-app project root."
}
if (-not (Test-Path $PackagePath)) { throw "package.json not found." }

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path $Target) | Out-Null
Copy-Item $PackagePath (Join-Path $BackupDir "package.json") -Force
if (Test-Path $Target) { Copy-Item $Target (Join-Path $BackupDir "repair-cached-emet-failures.js") -Force }

try {
    $bytes = [Convert]::FromBase64String(@'

'@)
    [System.IO.File]::WriteAllBytes($Target, $bytes)

    $actual = (Get-FileHash $Target -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne "0f83c46e5ffeb8381c74e66396940c1ff897c3585e386ec2bcc3be3c735cb215") { throw "Installed repair script checksum mismatch." }

    $packageText = [System.IO.File]::ReadAllText($PackagePath)
    $packageText = $packageText.TrimStart([char]0xFEFF)
    $package = $packageText | ConvertFrom-Json
    if (-not $package.scripts) {
        $package | Add-Member -MemberType NoteProperty -Name scripts -Value ([pscustomobject]@{})
    }
    $command = "node --max-old-space-size=4096 scripts/entity/repair-cached-emet-failures.js"
    if ($package.scripts.PSObject.Properties.Name -contains "repair:cached-emet") {
        $package.scripts.'repair:cached-emet' = $command
    } else {
        $package.scripts | Add-Member -MemberType NoteProperty -Name 'repair:cached-emet' -Value $command
    }
    $json = $package | ConvertTo-Json -Depth 100
    [System.IO.File]::WriteAllText($PackagePath, $json + "`n", (New-Object System.Text.UTF8Encoding($false)))

    & node --check $Target
    if ($LASTEXITCODE -ne 0) { throw "Repair script syntax validation failed." }

    Write-Host ""
    Write-Host "Inspecting the targeted repair plan..." -ForegroundColor Cyan
    & npm run repair:cached-emet -- --plan
    if ($LASTEXITCODE -ne 0) { throw "Repair plan failed." }

    Write-Host ""
    Write-Host "P04 targeted final repair installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupDir"
    Write-Host ""
    Write-Host "Next command:"
    Write-Host "npm run repair:cached-emet -- --concurrency 3 --attempts 2" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "This command preserves all accepted caches and repairs only current failures."
}
catch {
    Write-Warning "Installation failed. Restoring package.json and previous repair script..."
    Copy-Item (Join-Path $BackupDir "package.json") $PackagePath -Force
    $oldRepair = Join-Path $BackupDir "repair-cached-emet-failures.js"
    if (Test-Path $oldRepair) { Copy-Item $oldRepair $Target -Force } elseif (Test-Path $Target) { Remove-Item $Target -Force }
    throw
}
